    finder(0, 0); finder(14, 0); finder(0, 14);
    for (var y = 0; y < size; y++) {
      for (var x = 0; x < size; x++) {
        var inFinder = (x < 8 && y < 8) || (x > 12 && y < 8) || (x < 8 && y > 12);
        if (!inFinder && bits[(x * 11 + y * 7) % bits.length]) {
